SELECT  primary_key as quotationCode ,type , quotation_name, quotation_number,
buyer, seller, seller_name,vender_data_code, enterprise_code as ownedEnterpriseCode,
user_code as userCode, user_name, language, payment_strategy, column_titles,
amount_title, product_detail,clauses_chs,clauses_en,quotation_time, state,
data_version,
sell_quotation,son_enterprise_code,delete_flag,business_belong
FROM  ${tableName}
WHERE
enterprise_code= #{enterpriseCode}
AND delete_flag= 'f'

    AND user_code IN

        #{userCode}



    AND quotation_number LIKE '%'|| #{quotationNumber} ||'%'


    AND seller_name  LIKE '%'|| #{sellerName} ||'%'


    AND state = #{state}


    AND quotation_time >= #{quotationTimePreDate}


    AND quotation_time <= #{quotationTimePostDate}


    AND business_belong = #{businessBelong}


    ${dataScopeParams.dataScope}

ORDER BY create_time DESC

