UPDATE ${tableName}
SET buyer        = #{model.buyer},
    user_code    = #{model.userCode},
    user_name    = #{model.userName},
    data_version = #{model.dataVersion},
    son_enterprise_code = #{model.sonEnterpriseCode}
WHERE enterprise_code = #{model.ownedEnterpriseCode}
  AND primary_key = #{model.quotationCode}
  AND data_version = #{clientDataVersion}

